export const layerNormalizationDefaults=()=>({mode:'strict',width:0,height:0,filter:'smooth'});
export function validLayerNormalization(value,dimension){if(value===undefined)return true;if(!value||typeof value!=='object'||Array.isArray(value)||Object.keys(value).some(k=>!['mode','width','height','filter'].includes(k))||dimension==='texture2d')return false;const p={...layerNormalizationDefaults(),...value};return ['strict','stretch','contain','cover'].includes(p.mode)&&['nearest','smooth'].includes(p.filter)&&[p.width,p.height].every(v=>Number.isSafeInteger(v)&&v>=0&&v<=16384)&&((p.width===0)===(p.height===0))&&(p.mode!=='strict'||p.width===0)&& (dimension!=='cubemap'||p.width===p.height);}
export const layerNormalizationPolicy=value=>({...layerNormalizationDefaults(),...value});
export function layerNormalizationSize(image,value,dimension){if(!validLayerNormalization(value,dimension))throw Error('레이어 원본 정규화 설정을 확인하세요.');const p=layerNormalizationPolicy(value),width=p.width||image.width,height=p.height||image.height;if(![width,height].every(v=>Number.isSafeInteger(v)&&v>0)||dimension==='cubemap'&&width!==height)throw Error('레이어 대상 크기·큐브 정사각형을 확인하세요.');return{width,height};}
export function drawNormalizedLayer(context,image,width,height,value){const p=layerNormalizationPolicy(value),sw=image.width,sh=image.height;if(![sw,sh,width,height].every(v=>Number.isSafeInteger(v)&&v>0))throw Error('레이어 원본 크기를 확인하세요.');if(p.mode==='strict'){if(sw!==width||sh!==height)throw Error('레이어 텍스처 이미지 크기를 맞춰 주세요.');context.drawImage(image,0,0);return false;}context.imageSmoothingEnabled=p.filter==='smooth';context.imageSmoothingQuality='high';if(p.mode==='stretch')context.drawImage(image,0,0,sw,sh,0,0,width,height);else if(p.mode==='contain'){const scale=Math.min(width/sw,height/sh),w=sw*scale,h=sh*scale;context.drawImage(image,0,0,sw,sh,(width-w)/2,(height-h)/2,w,h);}else{const scale=Math.max(width/sw,height/sh),w=width/scale,h=height/scale;context.drawImage(image,(sw-w)/2,(sh-h)/2,w,h,0,0,width,height);}return sw!==width||sh!==height;}
export const layerNormalizationContract=Object.freeze({property:'Optional layerNormalization on texturearray/cubemap/volumetexture; strict default preserves old equal-size rejection',fields:layerNormalizationDefaults(),modes:'stretch fills target; contain preserves aspect centered with transparent padding; cover preserves aspect and crops center; strict never resizes. Explicit width/height1..16384 together or0/0 uses first source; cubemap target square.',filter:'nearest disables canvas smoothing for pixel art; smooth uses native canvas high-quality image resampling. Decoded supported image formats are read as existing RGBA8; no compressed GPU/HDR conversion claim.',pipeline:'Same bounded reusable decode canvas, existing asynchronous mip cook/worker and real texture upload/preview. Authored mip targets halve with existing volume slice counts. Source images remain untouched; optional small report counts changed-size sources.',storage:'Normalization is opt-in; disk-authored mip streaming requires strict sizes and cannot be enabled together. No new worker/cache/sidecar/output image copies.',ai:'Same asset JSON/validator/normal edit/save/Undo and detached engine schema; invalid sizes/modes reject before runtime.'});
